/* Correctly rounded asin, acos, atan and atan2 for a fixed set of inputs, from
   CORE-MATH via gen/gen-atan-ref.c -- see gen/README.md.

   asin and acos live on [-1, 1] and are steepest at the ends, where the
   derivative is infinite and the implementation changes method, so a third of
   their points sit within 2^-20 of +/-1.  atan is tame on [-1, 1] and reduces
   by 1/x outside it, so a third of its points cover that boundary and a third
   spread to 2^60, where the answer approaches pi/2 and everything rides on how
   that constant is carried.  atan2 takes the same arguments in pairs.  The
   float tables need no such care -- these compute in double and convert.  */

